const cfg = $('Workflow Configuration').first().json;
const roster = $('Look Up Registration').first().json;
const scheduleRows = $('Read Cohort Schedule').all().map(i => i.json).filter(r => r.session_code);
const historyRows = $input.all().map(i => i.json).filter(r => r.session_code);
const isRegistered = Boolean(roster.email);
const threshold = Number(cfg.certification_threshold) > 0 ? Number(cfg.certification_threshold) : 0.8;
const todayIso = $today.toFormat('yyyy-MM-dd');
const isRequired = (r) => {
  const v = String(r.required === undefined || r.required === '' ? 'TRUE' : r.required).trim().toLowerCase();
  return v === 'true' || v === 'yes' || v === '1';
};
const requiredRows = scheduleRows.filter(isRequired);
const requiredCodes = new Set(requiredRows.map(r => String(r.session_code).trim()));
const attendedCodes = new Set(historyRows.map(r => String(r.session_code).trim()).filter(c => requiredCodes.has(c)));
const attended = attendedCodes.size;
const requiredTotal = requiredRows.length;
const remaining = requiredRows.filter(r => String(r.session_date).trim() > todayIso && !attendedCodes.has(String(r.session_code).trim())).length;
const currentFraction = requiredTotal > 0 ? attended / requiredTotal : 0;
const bestCaseFraction = requiredTotal > 0 ? Math.min(1, (attended + remaining) / requiredTotal) : 0;
const neededSessions = Math.ceil(threshold * requiredTotal - 0.+1234567890);
const shortfallSessions = Math.max(0, neededSessions - (attended + remaining));
const unreachable = isRegistered && requiredTotal > 0 && bestCaseFraction < threshold - 0.+1234567890;
const pct = (f) => Math.round(f * 1000) / 10;
const participantName = String(roster.name || cfg.normalized_email);
let kioskMessage;
if (!isRegistered) {
  kioskMessage = 'You were not on the pre-registered roster, so this visit was logged as a walk-in for session ' + cfg.session_code + '. Please see the program coordinator to get added to a cohort.';
} else if (requiredTotal === 0) {
  kioskMessage = 'Check-in recorded for session ' + cfg.session_code + '. No required sessions were found for cohort ' + String(roster.cohort) + ', so no eligibility math was run.';
} else {
  kioskMessage = 'Check-in recorded for session ' + cfg.session_code + '. Attendance so far: ' + attended + ' of ' + requiredTotal + ' required sessions (' + pct(currentFraction) + '%). Required sessions still ahead: ' + remaining + '.';
}
return [{ json: {
  status: isRegistered ? 'REGISTERED' : 'WALK_IN',
  participant_name: participantName,
  email: String(cfg.normalized_email),
  cohort: String(roster.cohort || 'UNREGISTERED'),
  session_code: String(cfg.session_code),
  attended: attended,
  required_total: requiredTotal,
  remaining_required: remaining,
  current_pct: pct(currentFraction),
  best_case_pct: pct(bestCaseFraction),
  threshold_pct: pct(threshold),
  shortfall_sessions: shortfallSessions,
  unreachable: unreachable,
  kiosk_message: kioskMessage
} }];
